%[text] # Exemple of LMI using the phasorArray toolbox
%[text] This script display a range of example of LMI built using the toolbox
%%
%[text] Creation of a random PhasorArray, using the "time\_structure" argument which specifies hurwitz
h=15;
nx=6;
T=1 %period %[output:520c1bf5]
A=(PhasorArray(rand_phasor(nx,nx,5,"time_structure","hurwitz","hurwitzeig",[(-1:-1:-nx)/10-2]))); %Creation of a PhasorArray object
A=mreal(A); %to extract only real part of A, rand_phasor can produce complex valued periodic matrices


N=N_tb(nx,h,T);

figure(10)
clf %[output:6fef7907]
stem(A) %[output:6fef7907]
sgtitle('Stem of A') %[output:6fef7907]
%[text] HmqNeig calculates the eigenvalues of (A-N), provided that A represents a square periodic matrix
figure(11)
plot(A.HmqNEig(h,T),'o') %[output:6fef7907]
title('eig(A-N)') %[output:6fef7907]

figure(12)
hmq_sim(A.Value,10,rand(nx,1),1,"plot",true); %[output:78e51d45] %[output:599003fc]
sgtitle("\dot x = A(t)x",'Interpreter','tex') %[output:599003fc]

figure(13)
plot(A,T,0:0.01:2,title='A(t)') %[output:599003fc]
%%
%[text] ## Stability
%[text] ### Do first the product between phaseor objects, then construct the Toeplitz Blocks Matrix
h=10 %[output:7b26b3a3]

P=PhasorArray.ndsdpvar(size(A,1),size(A,1),h,"PhasorType",'symmetric',"real",true) %[output:20f34cac]

PT=P.T_tb(h);
t1=tic();

%product between phaseor objects
ATP=(A.')*P;
PA=P*A;
ATPpPA=(ATP+PA) %[output:5e9294e7]

%Building the Toeplitz Blocks Matrix
ATPpPA.T_tb(h);

F=[PT>=0,ATPpPA.T_tb(h) + N_tb(nx,h,1)*PT-PT*N_tb(nx,h,1)<=-(eye(size(A.T_tb(h),1))*10)] %[output:9bec489a]
toc(t1) %[output:0a0005ea]
optimize(F) %[output:5b126ce6] %[output:0ca497fb]
toc(t1) %[output:3c1ef137]
%
Pf=sdpval(P);

figure(20)
Pf.plot %[output:3875a273]
sgtitle("P(t)") %[output:3875a273]
%%
%[text] ### Stability analysis, using the corrective TB hankel matrices
h=10 %[output:683c3645]

t1=tic();
P=PhasorArray.ndsdpvar(size(A,1),size(A,2),h,"PhasorType",'symmetric',"real",true) %[output:5376e934]

PT=P.T_tb(h);
ATB=A.T_tb(h);

[AHpJ,~,~,AHm]=A.TBHankel(h);
[~,AtJHm,AtHp,~]=TBHankel(A.',h);
[PHpJ,PJHm,PHp,PHm]=P.TBHankel(h);
F=[PT>=0; %[output:group:28416ee7] %[output:7dede82a]
(ATB'+N_tb(A,h))*PT+PT*(ATB-N_tb(A,h))+... %[output:7dede82a]
AtHp*PHm+PHp*AHm+... %[output:7dede82a]
AtJHm*PHpJ+PJHm*AHpJ<=0] %[output:group:28416ee7] %[output:7dede82a]

toc(t1) %[output:511641af]
optimize(F) %[output:4ee2ccd2] %[output:276e3b25]
toc(t1) %[output:66d39822]
%
Pf=sdpval(P) %[output:02d988b6]

figure(21)
clf %[output:4d137251]
Pf.plot %[output:4d137251]
sgtitle("P(t)") %[output:4d137251]


%%
%[text] ## quadratic stability
hP=10;
h=10;
hb=3 %[output:1c7fea13]

nx=2 %[output:55150661]
nu=2 %[output:06a33e37]

T=5;

A=mreal(rand_phasor(nx,nx,hb,output="PhasorArray")) %[output:488614e0]

Q=PhasorArray.ndsdpvar(nx,nx,hP,PhasorType='symmetric') %[output:31740ff0]
QT=Q.T_tb(h);

%produits entre les objets phaseur
QAT=Q*(A.') %[output:6e9e6bdc]
AQ=A*Q %[output:2e554063]
QATpAQ=(QAT+AQ) %[output:1b353742]
% LMI=QATpAQ+Y+(Y.')

% Construction of the Toeplitz Blocks Matrix (matrix with Toeplitz blocks)
QATpAQ.T_tb(2*h);


B=rand_phasor(nx,nu,hb);
Y=PhasorArray.ndsdpvar(nx,nx,hP,PhasorType='full') %[output:5b473adc]

F=[QT>=eye(size(QT))];
N=N_tb(A,h,T);
F=[F,[QATpAQ.T_tb(h)-N*QT+QT*N+Y.T_tb(h)+Y.T_tb(h)'] <=-8*QT] %[output:9cf48a22]

optimize(F,-trace(Y.phas(0))) %[output:086f9771] %[output:1d9c79ad]


%
Pf=sdpval(P);

figure(22)
Q.plot(explosed=true); %[output:30ae26d8]
sgtitle("Q(t)") %[output:30ae26d8]


figure(23)
Y.plot(explosed=true); %[output:30ae26d8]
sgtitle("Y(t)") %[output:30ae26d8]

%%\

K=sdpval(Y)/sdpval(Q); %[output:744983c7]
K=PhasorArray(value(value(K))) %[output:1fa43b01]
figure(24)
plot(K) %[output:42c7fdc2]

figure(25)
plot(A.HmqNEig,'*') %[output:42c7fdc2]
hold on %[output:42c7fdc2]
plot(HmqNEig(A+K),'o') %[output:42c7fdc2]

figure(26)
lsim(A+K,2,[],T); %[output:9342c2af]

%%
%[text] ## LQ reg H2
nx=3;
nu=3;
nha=3;
hP=10;
h=10;

T=1/2/pi %[output:2caeb6be]
x0=[1 0 0] %[output:17e3f2b5]

Q=eye(nx) %[output:34375810]
R=eye(nu) %[output:940f7ae6]

A=mreal(rand_phasor(nx,nx,nha,'output','PhasorArray'));
B=mreal(rand_phasor(nx,nu,nha,'output','PhasorArray'));

X=PhasorArray.ndsdpvar(nx,nx,hP);
W=PhasorArray.ndsdpvar(nu,nx,hP,'PhasorType','full','real',1);
Y=PhasorArray.ndsdpvar(nu,nu,hP) %[output:4b23f911]
Gam=sdpvar(1) %[output:543c45c3]

M1=(A*X+B*W)+(A*X+B*W).'+x0*x0';
M2=phas(trace((Q^0.5)*X*(Q^0.5).')+trace(Y),0);
M3=[-Y (R^0.5)*W;((R^0.5)*W).' -X];


N=N_tb(A,h,T);
F=[[M1.T_tb(h)-N'*X.T_tb(h)-X.T_tb(h)*N<=0];... %[output:group:612bd19e] %[output:06d2f9e9]
    M2<=Gam;... %[output:06d2f9e9]
    M3.T_tb(h)<=0] %[output:group:612bd19e] %[output:06d2f9e9]

obj=Gam %[output:3d01becc]

optimize(F,obj) %[output:95919dc8] %[output:7a6179b3]

K=(sdpval(W)/sdpval(X))%display controller matrix %[output:3883a633] %[output:65f034ba]
K=PhasorArray(value(value(K))) %[output:9d493ace]
figure(27)
plot(K) %[output:55676468]


figure(28)
plot(A.HmqNEig(h,T),'*') %[output:55676468]
hold on %[output:55676468]
plot((HmqNEig(A+B*K,h,T)),'o') %[output:55676468]

figure(29)
lsim(A+B*K,2,[],T); %[output:1649cd39]

value(value(Gam)) %[output:8e5a18a2]

%%
%[text] ## Another H\_2 
nx=3;
nu=3;
ny=2
nha=3;
hP=10;
h=10;


A=mreal(rand_phasor(nx,nx,nha,'output','PhasorArray'));
B=mreal(rand_phasor(nx,nu,nha,'output','PhasorArray'));
B=mreal(rand_phasor(ny,nx,nha,'output','PhasorArray'));

X=PhasorArray.ndsdpvar(nx,nx,hP);
W=PhasorArray.ndsdpvar(nu,nx,hP,'PhasorType','full','real',1);
Y=PhasorArray.ndsdpvar(nu,nu,hP)
Gam=sdpvar(1)



%%
%[text] ## LQR
nx=3;
nu=3;
ny=2 %[output:54ceeab5]
nha=3;
hP=10;
h=10;

T=1/10 %[output:80ecddfb]


A=mreal(rand_phasor(nx,nx,nha,'output','PhasorArray'));
B=mreal(rand_phasor(nx,nu,nha,'output','PhasorArray'));
C=mreal(rand_phasor(ny,nx,nha,'output','PhasorArray'));


Y=PhasorArray.ndsdpvar(nx,nx,hP);
L=PhasorArray.ndsdpvar(nu,nu,hP) %[output:83c3b7aa]
Gam=sdpvar(1) %[output:6fffc7d9]

%Forme Toeplitz Block de Q 
YT=Y.T_tb(h);

B=PhasorArray(eye(nx));
LMI=(A*Y + B*L)+(A*Y+B*L).';

Ql= PhasorArray(diag(10*ones(nx,1)));
Rl= PhasorArray(diag(1*ones(nx,1)));

F=[YT>=0];
N=N_tb(A,h,T);

F=[F,[-(LMI.T_tb(h)-N*YT-YT*N'), Y.T_tb(h) , L.T_tb(h)';
Y.T_tb(h) , T_tb(Ql^-1,h),  -zeros((2*h+1)*nx);
L.T_tb(h), -zeros((2*h+1)*nx), T_tb(Rl^-1,h)] >=0];

obj=-trace(Y).phas(0);
u=optimize(F,obj); %[output:315f8152]


figure(30)
Y.plot(plot=true,explosed=true); %[output:209f3f39]
sgtitle("Y(t)") %[output:209f3f39]


figure(31)
L.plot(plot=true,explosed=true); %[output:209f3f39]
sgtitle("L(t)") %[output:209f3f39]

if ~u.problem %si le solver a trouvé une solution %[output:group:10c973dc]
    K=sdpval(L)/sdpval(Y); %[output:0fbd1581]
end %[output:group:10c973dc]

K=K.sdpval %[output:8a48d259]
K=K.reduce("reduceMethod","relative","reduceThreshold",1e-4) %[output:94c57bff]

figure(34)
K.plot(plot=true,explosed=true); %[output:209f3f39]
sgtitle("K(t)") %[output:209f3f39]

figure(35)
K.stem %[output:209f3f39]
sgtitle("K") %[output:209f3f39]

figure(36)
plot(A.HmqNEig(h,T),'*') %[output:209f3f39]
hold on %[output:209f3f39]
plot(value(HmqNEig(A+B*K,h,T)),'o') %[output:209f3f39]

figure(37)
lsim(A+B*K,2,[],T); %[output:59d30780]
%%
%[text] ## LQR

Q=PhasorArray.ndsdpvar(size(A,1),size(A,2),h,"PhasorType",'symmetric',"real",true) %[output:30c846ae]


%idem pour Y
Y=PhasorArray.ndsdpvar(size(A,1),size(A,2),h,"PhasorType","full","real",true) %[output:9702313f]

%Forme Toeplitz Block de Q 
QT=Q.T_tb(h);

B=PhasorArray(eye(nx));
LMI=(A*Q + B*Y)+(A*Q+B*Y).';

Ql= PhasorArray(diag(10*ones(nx,1)));
Rl= PhasorArray(diag(1*ones(nx,1)));


F=[QT>=0];
N=N_tb(A,h,1);

F=[F,[LMI.T_tb(h)-N*QT-QT*N', -Q.T_tb(h) , -Y.T_tb(h)';
-Q.T_tb(h) , -T_tb(Ql^-1,h),  -zeros((2*h+1)*nx);
-Y.T_tb(h), -zeros((2*h+1)*nx), -T_tb(Rl^-1,h)] <=0];

obj=trace(Y);
u=optimize(F,obj.phas(0)); %[output:435bfafb]


figure(40)
Q.plot(plot=true,explosed=true); %[output:3d4253bf]
sgtitle("Q(t)") %[output:3d4253bf]


figure(41)
Y.plot(plot=true,explosed=true); %[output:3d4253bf]
sgtitle("Y(t)") %[output:3d4253bf]

if ~u.problem %si le solver a trouvé une solution %[output:group:16d86e59]
    K=sdpval(Y)/sdpval(Q); %[output:400829fb] %[output:89e81ff8] %[output:41ac7ceb] %[output:3980bc10]
end %[output:group:16d86e59]

figure(42)
K.plot(plot=true,explosed=true); %[output:3d4253bf]
sgtitle("K(t)") %[output:3d4253bf]

figure(43)
K.stem %[output:3d4253bf]
sgtitle("K") %[output:3d4253bf]
%%
x0=rand(nx,1);
figure(44)
subplot(121) %[output:259f1fd5]
hmq_sim(A,4,x0,1,"plot",true); %[output:3e91b661] %[output:259f1fd5]
title("dx =(A(t)) x") %[output:259f1fd5]

subplot(122) %[output:6cb19104]
hmq_sim(A+B*K,4,x0,1,"plot",true); %[output:58188550] %[output:7c21ca60] %[output:58fe76cc] %[output:674fc75e] %[output:6cb19104]
title("dx =(A+BK) x") %[output:6cb19104]
sgtitle('memes conditions initiales') %[output:6cb19104]

figure(45)
K.plot(plot=true,explosed=true); %[output:6cb19104]
sgtitle("K(t)") %[output:6cb19104]
%%
%[text] ## Riccati LMI
%[text] $A^T P +PA -(PB +N^T)R^{-1}(B^T P +N) + Q \\geq 0$
%[text] $\\left\[\\matrix{A^TP +PA  +Q & PB +N^T \\cr (PB +N^T)^T & R} \\right\] \>0$
%[text] 
nx=2;
nu=2;

ha=3; %A truncature order
hP=10; %P truncature order
h=10;  %LMI truncature order

T=3; %period

A=PhasorArray.random(nx,nx,ha,"time_structure","real");
figure(500)
clf %[output:9ca8bef7]
A.plot(T) %[output:9ca8bef7]
figure(501)
clf %[output:92f561d5]
plot(A.HmqNEig,'*') %[output:92f561d5]


B=rand_phasor(nx,nu,ha,"output","PhasorArray");

%%%%% controllability criteria
%%% (A-N)W + W(A-N) + BB' iff Re(eig(A-N))<0

Pc=mreal(PhasorArray(SylvHarmonic(A,A',B*B.',2*hP,1)));
figure(502) %[output:9f788e11]
plot(Pc) %[output:9f788e11]
trace(Pc).phas(0) %[output:39c78866]
 

%ndsdpvar phasor array
P=PhasorArray.ndsdpvar(nx,nx,hP,"PhasorType",'symmetric',"real",true) %[output:1a684da6]
PT=P.T_tb(h);

Q=PhasorArray(eye(nx));
QT=Q.T_tb(h);

R=PhasorArray(eye(nu));
RT=Q.T_tb(h);

N=PhasorArray(zeros(nu,nx));


[AHpJ,AJHm,AHp,AHm]=A.TBHankel(h);
[AtHpJ,AtJHm,AtHp,AtHm]=TBHankel(A.',h);

[PHpJ,PJHm,PHp,PHm]=P.TBHankel(h);
[BHpJ,BJHm,BHp,BHm]=B.TBHankel(h);

ATB=A.T_tb(h);
BTB=B.T_tb(h);

NT=N.T_tb(h);

F0=[PT>=0] %[output:11a6d21a]

F11=[ATB'*PT+PT*ATB+...
AtHp*PHm+PHp*AHm+...
AtJHm*PHpJ+PJHm*AHpJ+...
N_tb(A,h,T)*PT-PT*N_tb(A,h,T)+QT];

F12=[PT*BTB+PHp*BHm+PJHm*BHpJ+NT'];

F21=F12';

F22=R.T_tb(h);

F1=[F11,F12;F21,F22];


F=[F0,F1>=0] %[output:74339a88]

obj=-trace(PT) %[output:59e85365]
optimize(F,obj) %[output:4108bd8b] %[output:0791787f]


PP=PhasorArray(value(P.value)) %[output:620ce95a]
figure(503) %[output:39eabd77]
plot(PP,T,'title','P(t)') %[output:39eabd77]

K=R\(B.'*PP+N) %[output:72a2fb77] %[output:4217f57c]

figure(504) %[output:3e8571e1]
plot(K,T,'title','K(t)') %[output:3e8571e1]

figure(505) %[output:11a0f87f]
plot((HmqNEig(A-B*K,10,T)),'*') %[output:11a0f87f]
hold on %[output:11a0f87f]
plot((HmqNEig(A,10,T)),'o') %[output:11a0f87f]

figure(506) %[output:79cdb355]
yyaxis left %[output:79cdb355]
lsim(A-B*K,10,[],T); %[output:79cdb355]

hold on %[output:79cdb355]
yyaxis right %[output:79cdb355]
lsim(A,10,[],T); %[output:79cdb355]


figure(507) %[output:0e117b33]
ii=1;
for T=logspace(-1,1,5) %[output:group:2b88596e]
subplot(5,1,ii) %[output:0e117b33]
lsim(A-B*K,2,[],T); %[output:0e117b33]
ii=ii+1 %[output:267ca705] %[output:52ee0553] %[output:6bdfc626] %[output:479d8db8] %[output:5fc8ae05]
end %[output:group:2b88596e]

%%
%[text] ## H2 LMI
%[text] $A^T P +PA +\\gamma^{-1}PBB^T P + C^TC  \\leq 0$
%[text] $\\left\[\\matrix{A^TP +PA  +C^TC & PB  \\cr (PB)^T & -\\gamma I} \\right\] \<0$
%[text] 
nx=2;
nu=2;
ny=2;

ha=3; % A truncature order
hP=10 ;%number of phasors in P, decision variable
h=10; %LMI truncature order

T=3; %period

A=PhasorArray.random(nx,nx,ha);
figure(500)
clf %[output:33d22898]
A.plot(T) %[output:33d22898]
figure(501)
clf %[output:911debb1]
plot(A.HmqNEig,'*') %[output:911debb1]


B=PhasorArray.random(nx,nu,ha);
C=PhasorArray.random(ny,nx,ha);

gam=PhasorArray.ndsdpvar(1,1,0)*eye(nu) %[output:0ab0d3c0]

%sdpvar phaseur array
P = PhasorArray.ndsdpvar(nx,nx,hP);
PT=P.T_tb(h);

Q=C.'*C;
QT=Q.T_tb(h);

[AHpJ,AJHm,AHp,AHm]=A.TBHankel(h);
[AtHpJ,AtJHm,AtHp,AtHm]=TBHankel(A.',h);

[PHpJ,PJHm,PHp,PHm]=P.TBHankel(h);
[BHpJ,BJHm,BHp,BHm]=B.TBHankel(h);

ATB=A.T_tb(h);
BTB=B.T_tb(h);


F0=[PT>=0] %[output:1b310d7f]

F11=-[ATB'*PT+PT*ATB+...
AtHp*PHm+PHp*AHm+...
AtJHm*PHpJ+PJHm*AHpJ+...
N_tb(A,h,T)*PT-PT*N_tb(A,h,T)+QT];

F12=[PT*BTB+PHp*BHm+PJHm*BHpJ];

F21=F12';

F22=-gam.T_tb(h);

F1=[F11,F12;F21,F22];


F=[F0,F1<=0] %[output:02116097]

obj=trace(gam{:,:,0}) %[output:0ec3c80c]
optimize(F,obj) %[output:0d01ed4a] %[output:41151d82]


PP=PhasorArray(value(P.value)) %[output:5ebfc6cc]
figure(601) %[output:125a2a40]
plot(PP,T,'title','P(t)') %[output:125a2a40]

K=value(value(gam))\(B.'*PP) %[output:790fe708] %[output:46b4ff8b]

figure(602) %[output:173b2064]
plot(K,T,'title','K(t)') %[output:173b2064]

figure(603) %[output:925fd558]
plot((HmqNEig(A-B*K,10,T)),'*') %[output:925fd558]
hold on %[output:925fd558]
plot((HmqNEig(A,10,T)),'o') %[output:925fd558]

figure(604) %[output:99f6d597]
lsim(A-B*K,10,[],T); %[output:99f6d597]

figure(605) %[output:29493fba]
lsim(A,10,[],T); %[output:29493fba]


%%
figure(607) %[output:5da6cd75]
ii=1 %[output:0e271bdf]
for T=logspace(-1,1,5) %[output:group:5d8bc29b]
subplot(5,1,ii) %[output:5da6cd75]
lsim(A-B*K,2,[],T); %[output:5da6cd75]
ii=ii+1 %[output:248b6b57] %[output:4d29db7c] %[output:5c2f60ef] %[output:4c0f4a78] %[output:3afca813]
end %[output:group:5d8bc29b]


